insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000104', '00000000-0000-4000-8000-000000000001', 4, 2, 'Kuis: posisi tuts', 'quiz', null, null, 'treble', '4/4', '[{"question":"Nada C berada tepat di kiri…","choices":["Kelompok dua tuts hitam","Kelompok tiga tuts hitam","Tuts hitam mana saja"],"answer_index":0},{"question":"Jari nomor 1 di tangan kanan adalah…","choices":["Kelingking","Ibu jari","Jari tengah"],"answer_index":1},{"question":"Dalam not angka, Do ditulis sebagai…","choices":["0","1","8"],"answer_index":1}]'::jsonb)
