insert into public.modules (id, level, tier, title, description, duration_weeks, daily_minutes, weekly_targets, drill) values ('00000000-0000-4000-8000-000000000002', 2, 1, 'Lima jari dua tangan', 'Penomoran jari, postur duduk, dan tangan kiri di C3.', 2, 15, '["Mainkan C3 sampai G3 dengan tangan kiri, kelingking (jari 5) di C3.","Mainkan Twinkle Twinkle dengan tangan kanan, lalu bagian yang sama satu oktaf lebih rendah dengan tangan kiri."]'::jsonb, '{"title":"Lima jari kiri, C sampai G","notation":"C3/q, D3/q, E3/q, F3/q, G3/q, F3/q, E3/q, D3/q, C3/w","clef":"bass","bpm_start":60,"bpm_goal":80}'::jsonb)
