insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000201', '00000000-0000-4000-8000-000000000002', 1, 1, 'Penomoran jari dan postur', 'text', 'Kedua tangan memakai nomor yang sama: ibu jari 1, kelingking 5. Duduk dengan siku sejajar tuts, jari melengkung seperti memegang bola kecil. Coba tekan C3 dengan jari 5 kiri dan C4 dengan jari 1 kanan.', null, 'treble', '4/4', null)
