insert into public.modules (id, level, tier, title, description, duration_weeks, daily_minutes, weekly_targets, drill) values ('00000000-0000-4000-8000-000000000004', 4, 2, 'Bass Clef dan durasi not', 'Membaca Bass Clef, lalu whole note, half note, dan quarter note.', 3, 20, '["Hafalkan not di garis Bass Clef dari bawah: G B D F A.","Hitung keras-keras whole note (4), half note (2), dan quarter note (1) sambil bermain.","Mainkan satu lagu tangan kiri di Bass Clef tanpa salah ketukan."]'::jsonb, '{"title":"Garis Bass Clef naik-turun","notation":"G2/q, B2/q, D3/q, F3/q, A3/q, F3/q, D3/q, B2/q, G2/w","clef":"bass","bpm_start":60,"bpm_goal":90}'::jsonb)
