insert into public.modules (id, level, tier, title, description, duration_weeks, daily_minutes, weekly_targets, drill) values ('00000000-0000-4000-8000-000000000005', 5, 2, 'Ritme: rest, dotted, eighth note', 'Menghitung diam, not bertitik, dan eighth note dengan hitungan 1-dan-2.', 3, 20, '["Hitung setiap rest dengan suara; jangan dilewati.","Mainkan pola dotted quarter + eighth dengan hitungan 1-dan-2.","Mainkan Ode to Joy dengan ritme dotted di 90 BPM."]'::jsonb, '{"title":"Eighth note dan rest","notation":"C4/8, D4/8, E4/8, F4/8, G4/q, R/q, G4/8, F4/8, E4/8, D4/8, C4/h","clef":"treble","bpm_start":60,"bpm_goal":96}'::jsonb)
