insert into public.modules (id, level, tier, title, description, duration_weeks, daily_minutes, weekly_targets, drill) values ('00000000-0000-4000-8000-000000000006', 6, 3, 'Scale mayor: C, G, F', 'Pola whole-whole-half, penjarian ibu jari menyeberang, tiga scale pertama.', 4, 25, '["Mainkan scale C mayor satu oktaf dengan penjarian 1-2-3-1-2-3-4-5.","Tambahkan scale G mayor; ingat F# di nada ketujuh.","Tambahkan scale F mayor dengan penjarian 1-2-3-4-1-2-3-4; ingat Bb.","Mainkan ketiga scale berturut-turut di 96 BPM tanpa berhenti."]'::jsonb, '{"title":"Scale C mayor, eighth note","notation":"C4/8, D4/8, E4/8, F4/8, G4/8, A4/8, B4/8, C5/8, B4/8, A4/8, G4/8, F4/8, E4/8, D4/8, C4/q","clef":"treble","bpm_start":60,"bpm_goal":96}'::jsonb)
