insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000602', '00000000-0000-4000-8000-000000000006', 2, 1, 'Scale C mayor', 'interactive_sheet', 'Setelah jari 3 di E, ibu jari menyeberang di bawah ke F.', 'C4/q, D4/q, E4/q, F4/q, G4/q, A4/q, B4/q, C5/q, B4/q, A4/q, G4/q, F4/q, E4/q, D4/q, C4/h', 'treble', '4/4', null)
