insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000603', '00000000-0000-4000-8000-000000000006', 3, 2, 'Scale G mayor', 'interactive_sheet', 'Sama dengan C mayor, tapi nada ketujuh naik menjadi F#.', 'G4/q, A4/q, B4/q, C5/q, D5/q, E5/q, F#5/q, G5/q, F#5/q, E5/q, D5/q, C5/q, B4/q, A4/q, G4/h', 'treble', '4/4', null)
