insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000605', '00000000-0000-4000-8000-000000000006', 5, 4, 'Kuis: scale mayor', 'quiz', null, null, 'treble', '4/4', '[{"question":"Pola jarak scale mayor adalah…","choices":["W-W-H-W-W-W-H","W-H-W-W-H-W-W","H-W-W-W-H-W-W"],"answer_index":0},{"question":"Nada kres di scale G mayor adalah…","choices":["C#","F#","G#"],"answer_index":1},{"question":"Nada mol di scale F mayor adalah…","choices":["Bb","Eb","Ab"],"answer_index":0}]'::jsonb)
