insert into public.modules (id, level, tier, title, description, duration_weeks, daily_minutes, weekly_targets, drill) values ('00000000-0000-4000-8000-000000000007', 7, 3, 'Chord dasar dan dua tangan', 'Triad mayor, progresi I-IV-V-I, dan melodi dengan iringan chord.', 4, 25, '["Bentuk triad C, F, dan G dengan jari 1-3-5 tanpa melihat tangan.","Pindah C-F-G-C tanpa jeda di antara chord.","Mainkan whole note chord di tangan kiri sambil tangan kanan memainkan melodi lima nada.","Iringi Twinkle Twinkle dengan chord I-IV-V."]'::jsonb, '{"title":"Progresi I-IV-V-I","notation":"(C4 E4 G4)/h, (F4 A4 C5)/h, (G4 B4 D5)/h, (C4 E4 G4)/h","clef":"treble","bpm_start":60,"bpm_goal":90}'::jsonb)
