insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000701', '00000000-0000-4000-8000-000000000007', 1, 1, 'Apa itu triad', 'text', 'Triad adalah tiga nada yang dibunyikan bersama: nada dasar, terts, dan kwint. Triad C mayor berisi C, E, dan G. Coba tekan ketiganya di keyboard di bawah.', null, 'treble', '4/4', null)
