insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000702', '00000000-0000-4000-8000-000000000007', 2, 1, 'Triad C, F, G', 'interactive_sheet', 'Tiga chord ini cukup untuk mengiringi ratusan lagu.', '(C4 E4 G4)/w, (F4 A4 C5)/w, (G4 B4 D5)/w', 'treble', '4/4', null)
