insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000703', '00000000-0000-4000-8000-000000000007', 3, 2, 'Progresi I-IV-V-I', 'interactive_sheet', 'Dalam C mayor, I adalah C, IV adalah F, V adalah G. Pindah chord tepat di ketukan pertama.', '(C4 E4 G4)/q, (C4 E4 G4)/q, (F4 A4 C5)/q, (F4 A4 C5)/q, (G4 B4 D5)/q, (G4 B4 D5)/q, (C4 E4 G4)/h', 'treble', '4/4', null)
