insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000704', '00000000-0000-4000-8000-000000000007', 4, 3, 'Chord tangan kiri', 'interactive_sheet', 'Turunkan chord yang sama satu oktaf untuk tangan kiri. Posisi F dan G dibalik agar tangan tidak melompat jauh.', '(C3 E3 G3)/w, (C3 F3 A3)/w, (B2 D3 G3)/w, (C3 E3 G3)/w', 'bass', '4/4', null)
