insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000705', '00000000-0000-4000-8000-000000000007', 5, 4, 'Kuis: chord', 'quiz', null, null, 'treble', '4/4', '[{"question":"Triad C mayor berisi…","choices":["C E G","C F A","C D E"],"answer_index":0},{"question":"Dalam C mayor, chord V adalah…","choices":["F","G","A"],"answer_index":1},{"question":"Penjarian triad tangan kanan posisi dasar…","choices":["1-2-3","1-3-5","2-3-4"],"answer_index":1}]'::jsonb)
