insert into public.modules (id, level, tier, title, description, duration_weeks, daily_minutes, weekly_targets, drill) values ('00000000-0000-4000-8000-000000000008', 8, 3, 'Scale minor dan key signature', 'A minor natural dan harmonic, lalu membaca key signature.', 4, 30, '["Mainkan A minor natural lalu C mayor, dan dengarkan beda nuansanya.","Mainkan A minor harmonic dengan G# di nada ketujuh.","Kenali key signature satu kres (G mayor / E minor) dan satu mol (F mayor / D minor).","Mainkan E minor dan D minor harmonic dari ingatan."]'::jsonb, '{"title":"A minor natural, eighth note","notation":"A3/8, B3/8, C4/8, D4/8, E4/8, F4/8, G4/8, A4/8, G4/8, F4/8, E4/8, D4/8, C4/8, B3/8, A3/q","clef":"treble","bpm_start":60,"bpm_goal":100}'::jsonb)
