insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000801', '00000000-0000-4000-8000-000000000008', 1, 1, 'A minor natural', 'interactive_sheet', 'Tuts putih semua, tapi mulai dari A. Inilah relatif minor dari C mayor.', 'A3/q, B3/q, C4/q, D4/q, E4/q, F4/q, G4/q, A4/q, G4/q, F4/q, E4/q, D4/q, C4/q, B3/q, A3/h', 'treble', '4/4', null)
