insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000802', '00000000-0000-4000-8000-000000000008', 2, 2, 'A minor harmonic', 'interactive_sheet', 'Naikkan nada ketujuh menjadi G#. Lompatan F ke G# membuat scale ini terdengar khas.', 'A3/q, B3/q, C4/q, D4/q, E4/q, F4/q, G#4/q, A4/q, G#4/q, F4/q, E4/q, D4/q, C4/q, B3/q, A3/h', 'treble', '4/4', null)
