insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000805', '00000000-0000-4000-8000-000000000008', 5, 4, 'Kuis: minor', 'quiz', null, null, 'treble', '4/4', '[{"question":"Relatif minor dari C mayor adalah…","choices":["E minor","A minor","D minor"],"answer_index":1},{"question":"Scale minor harmonic menaikkan nada ke…","choices":["Tiga","Lima","Tujuh"],"answer_index":2},{"question":"Key signature satu mol (Bb) berarti…","choices":["G mayor / E minor","F mayor / D minor","D mayor / B minor"],"answer_index":1}]'::jsonb)
