insert into public.modules (id, level, tier, title, description, duration_weeks, daily_minutes, weekly_targets, drill) values ('00000000-0000-4000-8000-000000000009', 9, 4, 'Arpeggio', 'Arpeggio mayor dan minor dua oktaf dengan ibu jari menyeberang.', 4, 30, '["Arpeggio C mayor dua oktaf; ibu jari menyeberang tanpa hentakan.","Tambahkan arpeggio F dan G mayor.","Tambahkan arpeggio A minor dan E minor.","Mainkan kelima arpeggio di 108 BPM dalam eighth note."]'::jsonb, '{"title":"Arpeggio C dan F","notation":"C4/8, E4/8, G4/8, C5/8, G4/8, E4/8, C4/q, F4/8, A4/8, C5/8, F5/8, C5/8, A4/8, F4/q","clef":"treble","bpm_start":60,"bpm_goal":108}'::jsonb)
