insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000901', '00000000-0000-4000-8000-000000000009', 1, 1, 'Arpeggio C mayor', 'interactive_sheet', 'Nada-nada triad dimainkan satu per satu naik dua oktaf. Ibu jari menyeberang setelah jari 3.', 'C4/8, E4/8, G4/8, C5/8, E5/8, G5/8, C6/q, G5/8, E5/8, C5/8, G4/8, E4/8, C4/8, R/q', 'treble', '4/4', null)
