insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000902', '00000000-0000-4000-8000-000000000009', 2, 2, 'Arpeggio F dan G', 'interactive_sheet', 'Bentuk tangan sama dengan C, hanya titik awalnya yang bergeser.', 'F4/8, A4/8, C5/8, F5/8, C5/8, A4/8, F4/q, G4/8, B4/8, D5/8, G5/8, D5/8, B4/8, G4/q', 'treble', '4/4', null)
