insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000000904', '00000000-0000-4000-8000-000000000009', 4, 4, 'Kuis: arpeggio', 'quiz', null, null, 'treble', '4/4', '[{"question":"Arpeggio adalah…","choices":["Chord yang dimainkan satu per satu","Scale yang dimainkan cepat","Dua tangan bergantian"],"answer_index":0},{"question":"Arpeggio A minor berisi nada…","choices":["A C# E","A C E","A D F"],"answer_index":1}]'::jsonb)
