insert into public.modules (id, level, tier, title, description, duration_weeks, daily_minutes, weekly_targets, drill) values ('00000000-0000-4000-8000-000000000010', 10, 4, 'Dinamika dan tempo', 'Piano sampai forte, crescendo, ritardando, dan lagu klasik pertama.', 4, 30, '["Mainkan satu frase piano (p), lalu forte (f), tanpa mengubah tempo.","Latih crescendo naik dan diminuendo turun pada scale C mayor.","Mainkan ritardando di empat ketukan terakhir lagu.","Rekam Minuet in G dengan dinamika, lalu dengarkan ulang hasilnya."]'::jsonb, '{"title":"Für Elise, frase pembuka","notation":"E5/8, D#5/8, E5/8, D#5/8, E5/8, B4/8, D5/8, C5/8, A4/q","clef":"treble","bpm_start":60,"bpm_goal":100}'::jsonb)
