insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000001001', '00000000-0000-4000-8000-000000000010', 1, 1, 'Simbol dinamika: pp sampai ff', 'text', 'pp (pianissimo) sangat lembut, p (piano) lembut, mp dan mf di tengah, f (forte) keras, ff (fortissimo) sangat keras. Keras-lembutnya datang dari kecepatan jari menekan tuts, bukan dari menekan lebih dalam.', null, 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000001002', '00000000-0000-4000-8000-000000000010', 2, 2, 'Crescendo pada scale C', 'interactive_sheet', 'Mulai p di C4, makin keras sampai f di C5, lalu turun kembali lembut.', 'C4/q, D4/q, E4/q, F4/q, G4/q, A4/q, B4/q, C5/q, B4/q, A4/q, G4/q, F4/q, E4/q, D4/q, C4/h', 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000001003', '00000000-0000-4000-8000-000000000010', 3, 3, 'Für Elise (pembuka)', 'interactive_sheet', 'Beethoven menulis frase ini pianissimo dalam birama 3/8; di sini dirapikan ke 4/4 agar mudah dibaca. Biarkan E dan D# bergantian dengan ringan.', 'E5/8, D#5/8, E5/8, D#5/8, E5/8, B4/8, D5/8, C5/8, A4/q, R/8, C4/8, E4/8, A4/8, B4/q, R/8, E4/8, G#4/8, B4/8, C5/q, R/q', 'treble', '4/4', null)
  on conflict (id) do update set order_index = excluded.order_index, week = excluded.week, title = excluded.title, content_type = excluded.content_type, body = excluded.body, notation_data = excluded.notation_data, clef = excluded.clef, time_signature = excluded.time_signature, quiz = excluded.quiz;
insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000001004', '00000000-0000-4000-8000-000000000010', 4, 4, 'Minuet in G (pembuka)', 'interactive_sheet', 'Minuet dari buku catatan Anna Magdalena Bach, dalam birama 3/4: hitung 1-2-3. Mainkan mezzo forte.', 'D5/q, G4/8, A4/8, B4/8, C5/8, D5/q, G4/q, G4/q, E5/q, C5/8, D5/8, E5/8, F#5/8, G5/q, G4/q, G4/q', 'treble', '3/4', null)
