insert into public.modules (id, level, tier, title, description, duration_weeks, daily_minutes, weekly_targets, drill) values ('00000000-0000-4000-8000-000000000011', 11, 5, 'Sight-reading harian', 'Membaca musik baru tanpa berhenti, satu birama di depan jari.', 6, 30, '["Baca empat birama baru setiap hari dan jangan berhenti saat salah.","Latih mata melihat satu birama di depan jari.","Sight-reading di Bass Clef, empat birama sehari.","Sight-reading dengan eighth note dan rest.","Sight-reading dengan key signature satu kres.","Baca enam belas birama baru di 80 BPM dengan kurang dari tiga not salah."]'::jsonb, '{"title":"Bacaan pendek dengan lompatan","notation":"G4/q, E4/8, F4/8, G4/q, C5/q, B4/q, A4/8, G4/8, F4/h, E4/q, D4/q, C4/w","clef":"treble","bpm_start":60,"bpm_goal":100}'::jsonb)
