insert into public.modules (id, level, tier, title, description, duration_weeks, daily_minutes, weekly_targets, drill) values ('00000000-0000-4000-8000-000000000012', 12, 5, 'Repertoar klasik dan jazz', 'Chord seventh, ii-V-I, Prelude in C dari Bach, dan blues scale dengan rasa swing.', 6, 30, '["Pelajari tiga chord seventh: Dm7, G7, dan Cmaj7.","Mainkan progresi ii-V-I di C mayor tanpa melihat tangan.","Mainkan delapan birama pertama Prelude in C (Bach) sebagai broken chord.","Mainkan blues scale C dengan swing eighth.","Dalam satu sesi, mainkan satu lagu klasik dan satu progresi jazz.","Mainkan resital kecil: dua lagu tanpa berhenti, lalu rekam hasilnya."]'::jsonb, '{"title":"Progresi ii-V-I","notation":"(D4 F4 A4 C5)/w, (D4 F4 G4 B4)/w, (C4 E4 G4 B4)/w","clef":"treble","bpm_start":60,"bpm_goal":100}'::jsonb)
