insert into public.lessons (id, module_id, order_index, week, title, content_type, body, notation_data, clef, time_signature, quiz) values ('00000000-0000-4000-9000-000000001202', '00000000-0000-4000-8000-000000000012', 2, 2, 'ii-V-I di C', 'interactive_sheet', 'G7 dimainkan dengan inversi agar jari hampir tidak berpindah dari Dm7.', '(D4 F4 A4 C5)/h, (D4 F4 G4 B4)/h, (C4 E4 G4 B4)/w', 'treble', '4/4', null)
